import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p91_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor reverse_cumsum_cuda(torch::Tensor input, int64_t dim);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("reverse_cumsum_cuda", &reverse_cumsum_cuda,
          "Fused reverse cumulative sum (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Warp-shuffle inclusive prefix scan (left to right within warp)
__device__ __forceinline__ float warp_inclusive_scan(float val) {
    #pragma unroll
    for (int offset = 1; offset < 32; offset <<= 1) {
        float n = __shfl_up_sync(0xffffffff, val, offset);
        if ((threadIdx.x & 31) >= offset) val += n;
    }
    return val;
}

// Each block handles one row. The row is processed in tiles from RIGHT to LEFT.
// Within each tile, threads load elements in reverse order, perform inclusive scan,
// then write to the output. A carry is propagated from right-to-left across tiles.
//
// Grid: (num_rows,)  Block: (BLOCK_SIZE,)
// For rows longer than BLOCK_SIZE, we loop over tiles from tail to head.

#define BLOCK_SIZE 256

__global__ void reverse_cumsum_kernel(const float* __restrict__ input,
                                       float*       __restrict__ output,
                                       int64_t row_len) {
    const int64_t row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp_id = tid >> 5;
    const int num_warps = BLOCK_SIZE >> 5;  // 8

    __shared__ float warp_sums[8];  // one slot per warp

    const float* in_row  = input  + row * row_len;
    float*       out_row = output + row * row_len;

    // carry_in accumulates the running sum from previously processed (rightward) tiles
    float carry_in = 0.0f;

    // Number of full BLOCK_SIZE tiles, plus a possible partial tile at the head
    int64_t num_tiles = (row_len + BLOCK_SIZE - 1) / BLOCK_SIZE;

    // Process tiles from the tail (rightmost) to the head (leftmost)
    for (int64_t tile = num_tiles - 1; tile >= 0; tile--) {
        int64_t tile_start = tile * BLOCK_SIZE;          // inclusive, leftmost index of tile
        int64_t tile_end   = tile_start + BLOCK_SIZE;    // exclusive
        if (tile_end > row_len) tile_end = row_len;
        int64_t tile_len = tile_end - tile_start;        // elements in this tile

        // Each thread reads one element from this tile (or 0 if out of bounds)
        int64_t idx = tile_start + tid;
        float val = (tid < (int)tile_len) ? in_row[idx] : 0.0f;

        // Intra-warp inclusive prefix scan
        float scanned = warp_inclusive_scan(val);

        // Store each warp's total into shared memory
        if (lane == 31 || tid == (int)tile_len - 1) {
            warp_sums[warp_id] = scanned;
        }
        __syncthreads();

        // Compute warp-level prefix offsets (exclusive scan over warp_sums)
        // Only threads in the first warp do this
        float warp_offset = 0.0f;
        if (warp_id == 0) {
            float w = (lane < num_warps) ? warp_sums[lane] : 0.0f;
            float ws = warp_inclusive_scan(w);
            if (lane < num_warps) warp_sums[lane] = ws;
        }
        __syncthreads();

        // Each warp's offset = sum of all previous warps' totals + carry_in
        if (warp_id > 0) {
            warp_offset = warp_sums[warp_id - 1];
        }
        float final_val = scanned + warp_offset + carry_in;

        // Write result: output[idx] = reverse cumsum value
        if (tid < (int)tile_len) {
            out_row[idx] = final_val;
        }
        __syncthreads();

        // Update carry_in: total sum of this tile + old carry_in
        // = last warp's inclusive sum + warp offsets of last warp + carry_in
        // = warp_sums[num_warps-1] + carry_in  (warp_sums already hold inclusive warp prefix)
        carry_in += warp_sums[(tile_len - 1) / 32];
        // The warp_sums stored are the running prefix, so the last active warp's slot
        // holds the total for this tile (relative). We need the absolute tile total.
        // Recompute: tile total = carry_in was already updated above correctly via
        // warp_sums[last_warp_id], which = sum of all elements in this tile.
        // Actually warp_sums[warp_id] after the prefix pass = prefix sum of warp totals,
        // so the last active warp slot = total of the whole tile.
        // carry_in is updated correctly.
        __syncthreads();
    }
}

// Two-phase approach for correctness: process tiles right-to-left with proper carry.
// The kernel above has a subtle issue with warp_sums reuse. Use a cleaner version:

__global__ void reverse_cumsum_kernel_v2(const float* __restrict__ input,
                                          float*       __restrict__ output,
                                          int64_t row_len) {
    const int64_t row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp_id = tid >> 5;
    constexpr int NW = BLOCK_SIZE / 32;  // 8 warps

    __shared__ float smem[NW];   // warp totals / offsets
    __shared__ float s_carry;    // carry passed left across tiles

    const float* in_row  = input  + row * row_len;
    float*       out_row = output + row * row_len;

    if (tid == 0) s_carry = 0.0f;
    __syncthreads();

    int64_t num_tiles = (row_len + BLOCK_SIZE - 1) / BLOCK_SIZE;

    for (int64_t tile = num_tiles - 1; tile >= 0; tile--) {
        int64_t tile_start = tile * BLOCK_SIZE;
        int64_t tile_end   = min(tile_start + (int64_t)BLOCK_SIZE, row_len);
        int64_t tile_len   = tile_end - tile_start;

        int64_t idx = tile_start + tid;
        float val = (tid < (int)tile_len) ? in_row[idx] : 0.0f;

        // Intra-warp inclusive prefix scan
        float scanned = val;
        #pragma unroll
        for (int offset = 1; offset < 32; offset <<= 1) {
            float n = __shfl_up_sync(0xffffffff, scanned, offset);
            if (lane >= offset) scanned += n;
        }

        // Warp total into shared mem
        if (lane == 31) smem[warp_id] = scanned;
        else if (tid == (int)tile_len - 1) smem[warp_id] = scanned;
        __syncthreads();

        // First warp does inclusive prefix scan of warp totals
        if (warp_id == 0 && lane < NW) {
            float w = smem[lane];
            #pragma unroll
            for (int offset = 1; offset < NW; offset <<= 1) {
                float n = __shfl_up_sync(0xffffffff, w, offset);
                if (lane >= offset) w += n;
            }
            smem[lane] = w;
        }
        __syncthreads();

        // Each thread's final value = intra-warp scan + prefix of prior warp totals + carry
        float prior_warps = (warp_id > 0) ? smem[warp_id - 1] : 0.0f;
        float out_val = scanned + prior_warps + s_carry;

        if (tid < (int)tile_len) {
            out_row[idx] = out_val;
        }

        // Update carry: tile total = smem[last active warp index] + s_carry
        if (tid == 0) {
            int last_warp = ((int)tile_len - 1) / 32;
            s_carry += smem[last_warp];
        }
        __syncthreads();
    }
}

// Generic fallback using torch ops (called from C++ side)
torch::Tensor reverse_cumsum_cuda(torch::Tensor input, int64_t dim) {
    // Fast path: CUDA, float32, contiguous, dim is innermost (last) dim
    int64_t ndim = input.dim();
    int64_t actual_dim = (dim < 0) ? dim + ndim : dim;

    if (input.is_cuda() &&
        input.scalar_type() == torch::kFloat32 &&
        input.is_contiguous() &&
        actual_dim == ndim - 1) {

        int64_t row_len = input.size(actual_dim);
        int64_t num_rows = input.numel() / row_len;

        auto output = torch::empty_like(input);

        dim3 grid(num_rows);
        dim3 block(BLOCK_SIZE);

        reverse_cumsum_kernel_v2<<<grid, block>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            row_len
        );

        return output;
    }

    // Generic fallback
    return torch::cumsum(input.flip(dim), dim).flip(dim);
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a reverse cumulative sum operation along a specified dimension.

        Parameters:
            dim (int): The dimension along which to perform the reverse cumulative sum.
        """
    def __init__(self, dim):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Fast path for CUDA float32 contiguous tensors on the last (innermost) dimension.
        # Falls back to the standard PyTorch path for all other cases.
        if (x.is_cuda and x.is_contiguous() and
                x.scalar_type() == torch.float32 and
                (self.dim == x.dim() - 1 or self.dim == -1)):
            return _stark_get_extension().reverse_cumsum_cuda(x, self.dim)
        return torch.cumsum(x.flip(self.dim), dim=self.dim).flip(self.dim)
        # <<<END_IMPROVE>>>

